import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "बच्चा सिर नहीं संभाल पा रहा? बैठने या चलने में देर? मांसपेशियां ढीली? इसका एक कारण एस एम ए नाम की जेनेटिक बीमारी हो सकती है. इसकी जांच के बारे में, आखिर तक देखिए.",
 "एस एम ए यानी स्पाइनल मस्कुलर एट्रॉफी. इसमें रीढ़ की हड्डी की वे नसें धीरे धीरे खत्म होती हैं, जो मांसपेशियों को चलने का संदेश देती हैं. इससे मांसपेशियां कमज़ोर और पतली होती जाती हैं.",
 "इसका कारण है एस एम एन वन नाम का जीन. ज़्यादातर मरीज़ों में, इस जीन का एक हिस्सा, जिसे एक्सॉन सात कहते हैं, दोनों कॉपी से गायब होता है. एक मिलता जुलता जीन, एस एम एन टू, थोड़ा प्रोटीन बनाता है. इसकी जितनी ज़्यादा कॉपी, बीमारी आमतौर पर उतनी हल्की.",
 "एस एम ए के कई प्रकार हैं. टाइप वन में लक्षण जन्म से छह महीने के अंदर दिखते हैं. टाइप टू में छह से बारह महीने में. और टाइप थ्री और फोर में, बचपन के बाद या बड़े होने पर.",
 "यह बीमारी माता और पिता, दोनों से मिलती है. जिनके पास जीन की एक खराब कॉपी होती है, उन्हें कैरियर कहते हैं. कैरियर बिल्कुल स्वस्थ होते हैं, उन्हें पता भी नहीं होता. अगर माता और पिता दोनों कैरियर हों, तो हर प्रेगनेंसी में बच्चे को एस एम ए होने की संभावना, चार में से एक होती है.",
 "उत्तर भारत के एक अध्ययन में, बिना पारिवारिक इतिहास वाले लोगों में, लगभग अड़तीस में से एक व्यक्ति कैरियर पाया गया. कैरियर होना कोई बीमारी या शर्म की बात नहीं है. यह सिर्फ जानकारी है, जो परिवार की योजना में मदद करती है.",
 "जांच कैसे होती है? सिर्फ खून का एक सैंपल. एम एल पी ए नाम की तकनीक से, एस एम एन वन जीन की कॉपी गिनी जाती है. शून्य कॉपी, यानी बीमारी की पुष्टि. एक कॉपी, यानी कैरियर. दो कॉपी, आमतौर पर सामान्य. पर कुछ लोग दो कॉपी होते हुए भी कैरियर हो सकते हैं. इसलिए रिपोर्ट जेनेटिक काउंसलर से ज़रूर समझें.",
 "यह टेस्ट किसके लिए है? जिस बच्चे में एस एम ए के लक्षण हों. जिनके परिवार में एस एम ए हो. शादी या प्रेगनेंसी की योजना बना रहे जोड़े, कैरियर जांच के लिए. और अगर दोनों कैरियर हों, तो प्रेगनेंसी में बच्चे की जांच हो सकती है. यह जांच सिर्फ बीमारी के लिए होती है, बच्चे का लिंग नहीं बताया जाता.",
 "अच्छी खबर. अब एस एम ए का इलाज है, और भारत में भी दवा उपलब्ध है. इलाज जितनी जल्दी, लक्षण आने से पहले शुरू हो, उतना बेहतर असर होता है. दुर्लभ रोग नीति के तहत आर्थिक सहायता भी मिल सकती है. इलाज का फैसला सिर्फ विशेषज्ञ डॉक्टर करते हैं.",
 close_voice("क्या आपने कभी एस एम ए के बारे में सुना था?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/smar_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/sma_{i}.wav"],check=True); f=f"/tmp/sma_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/sma_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
